create table if not exists public.mk_chat_messages (id uuid primary key default gen_random_uuid(),nick text not null,message text not null,ip_hash text not null,created_at timestamptz not null default now());create index if not exists mk_chat_messages_created_at_idx on public.mk_chat_messages(created_at desc);create index if not exists mk_chat_messages_ip_hash_idx on public.mk_chat_messages(ip_hash);create table if not exists public.mk_chat_bans (ip_hash text primary key,reason text,created_at timestamptz not null default now());create table if not exists public.mk_site_settings (id integer primary key default 1,player_url text not null default '',now_label text not null default 'Magic Kids TV',later_label text not null default 'Próximamente',updated_at timestamptz not null default now());insert into public.mk_site_settings(id) values(1) on conflict(id) do nothing;alter table public.mk_chat_messages enable row level security;alter table public.mk_chat_bans enable row level security;alter table public.mk_site_settings enable row level security;